    sort_loop (Z.to_nat (hs_nbSymbols h)) 0 ws rs (repeat None 256) = Ok (rs2, syms) /\
    fill_weights (Z.to_nat tl) 1 tl rank syms (repeat None (Z.to_nat (2 ^ (L + 1)))) (Znth 0 rank) 0 = Ok cells /\
    x1_table_ok (x1_cells cells) tl /\ zlen cells = 2 ^ (L + 1) /\
    (forall i, 0 <= i < 2 ^ tl -> exists c, nth (Z.to_nat i) cells None = Some c).
