Section CANSEC. Context {rc : runConstT}.
Section TOP.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : fmem) (DT W S mtl lo : Z) (src : list Z).
  Notation SP := (bv_unsigned sp).
  Notation FB := (bv_unsigned sp - 176).
  Notation POST := (huf_rdt_post huf_dt_ok ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DT W S mtl src lo m).
  Notation WALL := [(bv_unsigned sp - HUF_RDT_STACK, bv_unsigned sp); (DT, DT + DTABLE_BYTES mtl); (W, W + 8704)].

  (* [comment removed for export] *)
  Lemma x1_epi : forall m' r (y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 y18 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30
                          y31 : word),
    176 <= SP ->
    rw_cells psegs m' (FB + 72) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk psegs m' lo (FB + 72) -> lo <= FB ->
    munch WALL m m' -> wmono psegs m m' -> mem_inv psegs m' -> 0 <= r < 2^64 -> (r < 2^64 - 119 -> huf_dt_ok m' DT mtl) ->
    evt psegs POST (MS (mkR y1 (Z_to_bv 64 FB) gp tp y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 y18 (Z_to_bv 64 r) y20 y21
                            y22 y23 y24 y25 y26 y27 y28 y29 y30 y31)
                       F (Z_to_bv 64 0x139f0) fc None m' (seg_rom psegs)).
