  (* [comment removed for export] *)
  Lemma x1_mid : forall m1 h jrest jdt RSj SYj jf (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 : word),
    read_stats src = Ok h -> Forall (fun c => 0 <= c < 256) src -> 1 <= mtl <= 12 ->
    0 < DT -> DT + 4 * (1 + 2 ^ mtl) <= lo -> 0 < W -> W + 8704 <= lo -> lo <= SP - 4096 -> SP <= 2 ^ 47 ->
    hk (DT + 4 * (1 + 2 ^ mtl) <= W \/ W + 8704 <= DT) ->
    rw_cells psegs m1 DT [C4 (Z_to_bv 64 (mtl * 16777217))] ->
    u8arr psegs m1 (DT + 4) jdt -> length jdt = Z.to_nat (4 * 2 ^ mtl) ->
    u8arr psegs m1 (W + 1236) (map (Z_to_bv 8) (hs_weights h) ++ jrest) -> zlen jrest = 256 - hs_nbSymbols h ->
    u32arr psegs m1 W (map (Z_to_bv 64) (hs_rank h)) ->
    u8arr psegs m1 (W + 52) RSj -> length RSj = 52%nat ->
    u8arr psegs m1 (W + 980) SYj -> length SYj = 256%nat ->
    rw_cells psegs m1 (FB + 16) [CB 48 jf] ->
    rw_cells psegs m1 (FB + 64) [C4 (Z_to_bv 64 (hs_nbSymbols h)); C4 (Z_to_bv 64 (hs_tableLog h))] ->
    rw_cells psegs m1 (FB + 72) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk psegs m1 lo FB -> wr_at psegs m FB 72 ->
    munch WALL m m1 -> wmono psegs m m1 -> mem_inv psegs m1 ->
    evt psegs POST (MS (mkR x1 (Z_to_bv 64 FB) gp tp x5 x6 x7 (Z_to_bv 64 W) (Z_to_bv 64 DT) (Z_to_bv 64 (hs_ret h))
                            x11 x12 x13 x14 x15 x16 x17 (Z_to_bv 64 (W + 1236)) (Z_to_bv 64 (-44)) s4 s5 s6 s7 s8 s9 s10 s11
                            x28 x29 x30 x31)
                       F (Z_to_bv 64 0x13488) fc None m1 (seg_rom psegs)).
Proof.
